#include "autotranslate.h"

#include "common/logging.h"

// Generated with this python script:
/*
# Builds the auto-translate rows for src/map/autotranslate.cpp.
#
# Phrases come from the client's ROM/168/25.DAT and key items from ROM/175/35.DAT. Item, zone,
# spell and ability names come from the sruon/FFXI-Resources NDJSON decode of the same client version.
#
# usage: python gen_table.py <FINAL FANTASY XI dir> <FFXI-Resources ndjson dir> <out.txt>

import json
import os
import struct
import sys

client_dir, resources_dir, out_path = sys.argv[1:4]

# 25.DAT refers to jobs by id ("@J1"), and the resource decode has no job table.
JOBS = [
    "", "Warrior", "Monk", "White Mage", "Black Mage", "Red Mage", "Thief", "Paladin", "Dark Knight",
    "Beastmaster", "Bard", "Ranger", "Samurai", "Ninja", "Dragoon", "Summoner", "Blue Mage",
    "Corsair", "Puppetmaster", "Dancer", "Scholar", "Geomancer", "Rune Fencer",
]

def load(name):
    with open(os.path.join(resources_dir, f"{name}.ndjson"), encoding="utf-8") as f:
        return [json.loads(line) for line in f if line.strip()]

def english(name):
    if isinstance(name, dict):
        return name.get("english", "")
    return name or ""

names = {
    "A": {r["id"]: english(r["name"]) for r in load("zones")},
    "C": {r["index"]: english(r["name"]) for r in load("spells")},
    "Y": {r["id"]: english(r["name"]) for r in load("abilities")},
    "J": dict(enumerate(JOBS)),
}

# 25.DAT is a list of categories, each a header and its entries:
# { u32 id, char display[32], char name[32], u32 count, u32 size } { u32 id, u8 length, char text[length] }...
# Ids are the wire bytes in order: type language category index.
with open(os.path.join(client_dir, "ROM", "168", "25.DAT"), "rb") as f:
    data = f.read()

phrases = []
pos = 0
while pos < len(data):
    category_id, = struct.unpack_from(">I", data, pos)
    phrases.append((category_id, data[pos + 36:pos + 68].split(b"\0")[0].decode("ascii")))
    count, = struct.unpack_from("<I", data, pos + 68)
    pos += 76
    for _ in range(count):
        key, = struct.unpack_from(">I", data, pos)
        length = data[pos + 4]
        phrases.append((key, data[pos + 5:pos + 5 + length].split(b"\0")[0].decode("ascii")))
        pos += 5 + length

rows = {}
for key, text in phrases:
    if text.strip() == "":
        continue
    if text.startswith("@"):
        text = names[text[1]].get(int(text[2:], 16), "")
        if text == "":
            raise SystemExit(f"Unresolved placeholder at {key:#010x}")
    rows[key] = text

# A zero byte can't go on the wire, so a zero id byte is sent as 0xFF with the type bumped.
def thing_key(base_type, thing_id):
    hi = thing_id >> 8
    lo = thing_id & 0xFF
    kind = base_type
    if hi == 0:
        kind = base_type + 2
        hi = 0xFF
    if lo == 0:
        kind = base_type + 3
        lo = 0xFF
    return kind << 24 | 0x02 << 16 | hi << 8 | lo

for r in load("items"):
    name = english(r["name"])
    if r["id"] == 0 or name.strip() in ("", "."):
        continue
    rows[thing_key(0x07, r["id"])] = name

# The resource decode numbers key items by row, so read ids and names from the client instead.
# ROM/175/35.DAT is a d_msg file: a 0x40 byte header, then fixed size entries XOR'd with 0xFF.
# An entry is { u32 field_count, (u32 offset, u32 type)[field_count] }, offsets from the entry start.
# Type 1 is a u32, type 0 a string after a 28 byte prefix. Field 0 is the id, field 4 the in-text name.
with open(os.path.join(client_dir, "ROM", "175", "35.DAT"), "rb") as f:
    data = f.read()

entry_size, data_size, count = struct.unpack_from("<III", data, 0x20)
for i in range(1, count):
    raw = bytes(b ^ 0xFF for b in data[0x40 + i * entry_size:0x40 + (i + 1) * entry_size])
    id_offset, = struct.unpack_from("<I", raw, 4)
    name_offset, = struct.unpack_from("<I", raw, 4 + 4 * 8)
    ki_id, = struct.unpack_from("<I", raw, id_offset)
    # Shift-JIS, except FFXI writes a right single quote as 0x85 0x52.
    name = raw[name_offset + 28:].split(b"\0")[0].replace(b"\x85\x52", b"\x81\x66").decode("cp932")
    if ki_id == 0 or name.strip() in ("", "."):
        continue
    rows[thing_key(0x13, ki_id)] = name

with open(out_path, "w", encoding="utf-8", newline="\n") as f:
    for key in sorted(rows):
        text = rows[key].replace("\\", "\\\\").replace('"', '\\"')
        f.write(f'    {{ 0x{key:08X}, "{text}" }},\n')

print(len(rows), "rows")
*/

